mapper.select:
SELECT EXISTS(
  SELECT 1 FROM audit_archive_batch b JOIN audit_archive_hold h ON h.scope_type=b.scope_type AND h.tenant_id=b.tenant_id
  WHERE b.batch_id=#{id} AND h.released_at IS NULL AND (
    h.resource_id IS NULL OR EXISTS (
      SELECT 1 FROM audit_archive_member m JOIN audit_operation_attempt a ON a.id=m.attempt_id
      LEFT JOIN platform_audit p ON p.audit_attempt_id=a.id
      WHERE m.batch_id=b.batch_id AND h.resource_id IN (a.resource_id,p.audit_resource_id)
    )
  )
)

SELECT r.attempt_id,r.payload,
  (SELECT JSON_ARRAYAGG(JSON_OBJECT('id',l.id,'kind',l.kind,'payload',l.payload,
    'recordedAt',DATE_FORMAT(l.recorded_at,'%Y-%m-%dT%H:%i:%s.%fZ')))
   FROM audit_archive_late_evidence l WHERE l.batch_id=r.batch_id AND l.attempt_id=r.attempt_id) AS late_evidence
FROM audit_archive_restored r JOIN audit_archive_restore_grant g ON g.ticket_id=r.ticket_id
JOIN audit_archive_batch b ON b.batch_id=g.batch_id
WHERE r.ticket_id=#{ticket} AND g.requested_by=#{actorId} AND b.tenant_id=#{tenantId} AND b.scope_type=#{scopeType}
  AND g.revoked_at IS NULL AND LEAST(r.expires_at,g.expires_at)>UTC_TIMESTAMP(3)
  AND r.attempt_id>#{after}
ORDER BY r.attempt_id LIMIT #{limit}
